function totalQuantity(items) { let total = 0; for (const item of items) total += item.quantity; return total; }
function availableNames(items) { const names = []; for (const item of items) if (item.quantity > 0) names.push(item.name); return names; }
function adjustQuantity(items, id, change) { const result = []; for (const item of items) result.push(item.id === id ? { ...item, quantity: Math.max(0, item.quantity + change) } : { ...item }); return result; }
function inventoryReport(items, id, change) { const adjusted = adjustQuantity(items, id, change); return { items: adjusted, total: totalQuantity(adjusted), available: availableNames(adjusted) }; }
function largestQuantity(items) { let largest = 0; for (const item of items) if (item.quantity > largest) largest = item.quantity; return largest; }
function lowStockNames(items, threshold) { const names = []; for (const item of items) if (item.quantity <= threshold) names.push(item.name); return names; }

