function totalQuantity(items) { let sum = 0; for (let i = 0; i < items.length; i++) sum = sum + items[i].quantity; return sum; }
function availableNames(items) { const result = []; for (let i = 0; i < items.length; i++) { if (items[i].quantity !== 0) result.push(items[i].name); } return result; }
function adjustQuantity(items, id, change) { return items.map((item) => ({ id: item.id, name: item.name, quantity: item.id === id ? Math.max(0, item.quantity + change) : item.quantity })); }
function inventoryReport(items, id, change) { const changed = adjustQuantity(items, id, change); return { available: availableNames(changed), total: totalQuantity(changed), items: changed }; }
function largestQuantity(items) { let max = 0; for (let i = 0; i < items.length; i++) max = Math.max(max, items[i].quantity); return max; }
function lowStockNames(items, threshold) { const result = []; for (let i = 0; i < items.length; i++) if (!(items[i].quantity > threshold)) result.push(items[i].name); return result; }

